<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { onBeforeRouteLeave, useRouter } from 'vue-router';
import { Modal, message } from 'ant-design-vue';
import { md5, sha256 } from 'hash-wasm';
import http from '../api/http';
import FontProductionSync from './FontProductionSync.vue';
const productionSync=ref<InstanceType<typeof FontProductionSync>>();
const syncOptions=ref<any>({can_sync:false,enabled:false});
import {missingFontCharacters} from './fontSpecimen';
const router=useRouter(),base='/api/v1/fonts/manage/';
const rows=ref<any[]>([]),count=ref(0),page=ref(1),query=ref(''),state=ref(''),busy=ref(false),error=ref('');
const options=ref<any>({permissions:{}}),selected=ref<any>(null),draft=ref<any>(null),assets=ref<any[]>([]),uploads=ref<any[]>([]);
const revision=ref(0),baseVersion=ref(0),saved=ref(''),activeTab=ref('basic'),preview=ref(false),checks=ref<string[]>([]),history=ref<any[]>([]);
const progress=ref(''),newOpen=ref(false),newTitle=ref(''),localFont=ref<File|null>(null),specimenURL=ref('');
const dirty=computed(()=>draft.value&&JSON.stringify(draft.value)!==saved.value);
const assetOptions=(kind:string)=>assets.value.filter(x=>x.kind===kind).map(x=>({value:x.id,label:`${x.metadata?.faces?.[0]?.family||x.kind} · ${(x.byte_size/1024).toFixed(0)} KB · ${x.id.slice(0,6)}`}));
const imageURL=(id:string)=>assets.value.find(x=>x.id===id)?.url;
const columns=[{title:'字体',key:'font'},{title:'线上版本',dataIndex:'version'},{title:'状态',key:'state'},{title:'推荐排序',key:'placement'},{title:'生产同步',key:'sync'},{title:'操作',key:'actions'}];
let generation=0;let timer:ReturnType<typeof setInterval>|undefined;
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e:any){error.value=JSON.stringify(e.response?.data||e.message||e)}finally{busy.value=false}}
async function load(){const r:any=await http.get(base+'families/',{params:{q:query.value,state:state.value,page:page.value}});rows.value=r.items;count.value=r.count}
async function create(){await run(async()=>{const r:any=await http.post(base+'families/',{title:newTitle.value});newOpen.value=false;await edit(r.id)})}
async function edit(id:string){const stamp=++generation;await run(async()=>{const r:any=await http.get(base+`families/${id}/draft/`);if(stamp!==generation)return;selected.value=r.family;draft.value=r.content;revision.value=r.revision;baseVersion.value=r.base_version;assets.value=r.assets;uploads.value=r.uploads;saved.value=JSON.stringify(r.content);checks.value=[];activeTab.value='basic'})}
async function refreshJobs(){if(!selected.value)return;const id=selected.value.id,stamp=generation;try{const r:any=await http.get(base+`families/${id}/draft/`);if(stamp!==generation)return;assets.value=r.assets;uploads.value=r.uploads}catch{/* explicit refresh exposes errors */}}
async function save(){const id=selected.value.id;const body=JSON.parse(JSON.stringify(draft.value));const r:any=await http.patch(base+`families/${id}/draft/`,{expected_revision:revision.value,content:body});revision.value=r.revision;saved.value=JSON.stringify(body);message.success('草稿已保存')}
async function publish(){await run(async()=>{if(dirty.value)await save();const r:any=await http.post(base+`families/${selected.value.id}/validate/`);checks.value=r.issues;if(checks.value.length)return;const key=crypto.randomUUID();Modal.confirm({title:'确认上架字体',content:`${draft.value.title} · 新版本 v${baseVersion.value+1}。发布后客户端可见，使用规则按已发布收费策略执行。`,onOk:async()=>{await http.post(base+`families/${selected.value.id}/publish/`,{expected_revision:revision.value,base_version:baseVersion.value,key});await edit(selected.value.id);message.success('字体已发布')}})})}
async function availability(row:any){Modal.confirm({title:row.active?'确认下架':'确认重新上架',content:'下架停止新获取，保留历史合法使用和已购恢复。',onOk:()=>run(async()=>{await http.patch(base+`families/${row.id}/availability/`,{active:!row.active});await load()})})}
async function upload(file:File,kind:string){const id=selected.value.id;progress.value='计算摘要';const bytes=new Uint8Array(await file.arrayBuffer());const mime=kind==='font'?(file.name.toLowerCase().endsWith('.otf')?'font/otf':'font/ttf'):(file.type||'text/plain');
const hex=await md5(bytes);const md5base=btoa(String.fromCharCode(...hex.match(/../g)!.map(x=>parseInt(x,16))));
const r:any=await http.post(base+'uploads/',{family:id,kind,name:file.name,byte_size:file.size,mime,md5:md5base,sha256:await sha256(bytes)});
progress.value='直传 OSS';const response=await fetch(r.url,{method:'PUT',headers:r.headers,body:file});if(!response.ok)throw new Error('OSS 上传失败，请重试');
progress.value='确认上传';await http.post(base+`uploads/${r.upload.id}/complete/`);await refreshJobs();progress.value='已上传，等待独立处理器验证';}
async function choose(event:Event,kind:string){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(kind==='font')localFont.value=file;await run(()=>upload(file,kind));(event.target as HTMLInputElement).value=''}
function addFace(asset:any){const face=asset.metadata.faces?.[0];if(!face)return;const id='face_'+asset.id.replaceAll('-','').slice(0,12);if(draft.value.faces.some((x:any)=>x.id===id))return;draft.value.faces.push({id,asset_id:asset.id,postscript_name:face.postscript_name,label:face.label||'Regular'});draft.value.default_face ||= id}
async function generate(){await run(async()=>{if(!localFont.value)throw new Error('请在字体文件页选择本地字体以生成真实小样');const bytes=await localFont.value.arrayBuffer();const missing=missingFontCharacters(bytes,draft.value.recipe.text);if(missing.length)throw new Error('小样缺字：'+missing.join(''));const name='specimen_'+Date.now();const font=new FontFace(name,bytes);await font.load();document.fonts.add(font);
try{const canvas=document.createElement('canvas');canvas.width=canvas.height=1024;const c=canvas.getContext('2d')!;c.fillStyle=draft.value.recipe.background||'#FFF6EB';c.fillRect(0,0,1024,1024);c.fillStyle='#F8CBD9';for(const [x,y] of [[150,160],[850,830]]){for(let n=0;n<5;n++){const a=n*Math.PI*2/5;c.beginPath();c.arc(x!+Math.cos(a)*30,y!+Math.sin(a)*30,24,0,Math.PI*2);c.fill()}}
c.fillStyle=draft.value.recipe.color||'#54483E';c.textAlign='center';c.font=`120px "${name}"`;const chars=Array.from(draft.value.recipe.text||'把日子写成诗');const mid=Math.ceil(chars.length/2);c.fillText(chars.slice(0,mid).join(''),512,450,820);c.fillText(chars.slice(mid).join(''),512,650,820);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('生成失败')),'image/png'));if(specimenURL.value)URL.revokeObjectURL(specimenURL.value);specimenURL.value=URL.createObjectURL(blob);await upload(new File([blob],'specimen.png',{type:'image/png'}),'cover');}finally{document.fonts.delete(font)}})}
async function price(){await run(async()=>{if(dirty.value)await save();await http.post('/api/v1/billing/manage/content-offers/',{target_kind:'font',target_id:selected.value.id});await router.push('/billing')})}
async function versions(){await run(async()=>{const r:any=await http.get(base+`families/${selected.value.id}/versions/`);history.value=r.items})}
function back(){if(dirty.value){Modal.confirm({title:'放弃未保存修改？',onOk:()=>{generation++;selected.value=null;draft.value=null;void load()}})}else{generation++;selected.value=null;draft.value=null;void load()}}
onBeforeRouteLeave(()=>!dirty.value||window.confirm('草稿有未保存修改，确认离开？'));
onMounted(()=>run(async()=>{options.value=await http.get(base+'options/');await load();timer=setInterval(refreshJobs,7000)}));
onUnmounted(()=>{generation++;if(timer)clearInterval(timer);if(specimenURL.value)URL.revokeObjectURL(specimenURL.value)});
</script>
<template>
<div class="fonts-admin"><FontProductionSync ref="productionSync" @options="value=>syncOptions=value" @synced="load()"/><a-breadcrumb><a-breadcrumb-item>内容资源</a-breadcrumb-item><a-breadcrumb-item>字体管理</a-breadcrumb-item></a-breadcrumb>
<a-alert v-if="error" :message="error" type="error" show-icon closable @close="error=''"/>
<a-alert v-if="syncOptions.can_sync&&!syncOptions.enabled" type="warning" :message="syncOptions.reason||'字体同步尚未配置'"/>
<template v-if="!selected"><header><h2>字体管理</h2><a-button v-if="options.permissions.edit" type="primary" @click="newOpen=true">新建字体</a-button></header>
<a-space wrap><a-input-search v-model:value="query" placeholder="搜索字体名称" @search="page=1;run(load)"/><a-select v-model:value="state" style="width:140px" :options="[{value:'',label:'全部状态'},{value:'draft',label:'未发布'},{value:'published',label:'已上架'},{value:'withdrawn',label:'已下架'}]"/><a-button @click="page=1;run(load)">查询</a-button><a-button @click="query='';state='';page=1;run(load)">重置</a-button></a-space>
<a-table :data-source="rows" :columns="columns" row-key="id" :loading="busy" :pagination="{current:page,total:count,pageSize:20}" @change="(p:any)=>{page=p.current;run(load)}"><template #bodyCell="{column,record}">
<template v-if="column.key==='font'"><img v-if="record.images[record.content.cover]" :src="record.images[record.content.cover]" class="thumb"/>{{record.title}}</template>
<template v-if="column.key==='state'"><a-tag>{{!record.version?'未发布':record.active?'已上架':'已下架'}}</a-tag></template>
<template v-if="column.key==='placement'">{{record.featured?'推荐 · ':''}}{{record.sort_order}}</template>
<template v-if="column.key==='sync'">{{record.production_sync?.label}}<small v-if="record.production_sync?.target_version"> · 生产 v{{record.production_sync.target_version}}</small></template>
<template v-if="column.key==='actions'"><a-space><a-button v-if="syncOptions.can_sync" :disabled="!syncOptions.enabled||!record.version||!record.active" type="link" @click="productionSync?.open(record)">同步到生产</a-button><a-button type="link" @click="edit(record.id)">编辑</a-button><a-button v-if="options.permissions.takedown&&record.version" type="link" @click="availability(record)">{{record.active?'下架':'上架'}}</a-button></a-space></template>
</template></a-table></template>
<template v-else-if="draft"><header><a-button @click="back">返回列表</a-button><h2>{{draft.title}}</h2><span>线上 v{{baseVersion}} · 草稿 {{revision}}</span></header>
<a-alert v-if="!options.processor_configured" type="warning" message="独立处理器尚未配置。上传后可保存草稿，验证完成前不能发布。"/>
<a-tabs v-model:active-key="activeTab">
<a-tab-pane key="basic" tab="基本信息"><a-form layout="vertical"><a-form-item label="字体名称"><a-input v-model:value="draft.title" :maxlength="120"/></a-form-item><a-form-item label="作者"><a-input v-model:value="draft.author"/></a-form-item><a-form-item label="简介"><a-textarea v-model:value="draft.description"/></a-form-item><a-form-item label="风格"><a-select v-model:value="draft.styles" mode="tags" :options="['手写','可爱','正文','标题','古风','圆体'].map(x=>({value:x,label:x}))"/></a-form-item><a-form-item label="语言"><a-select v-model:value="draft.languages" mode="tags" :options="['简体中文','繁体中文','英文'].map(x=>({value:x,label:x}))"/></a-form-item><a-form-item label="搜索别名"><a-select v-model:value="draft.aliases" mode="tags"/></a-form-item></a-form></a-tab-pane>
<a-tab-pane key="files" tab="字体文件"><p>静态 TTF / OTF，最大 100 MB。文件直接上传 OSS。</p><input v-if="options.permissions.upload" type="file" accept=".ttf,.otf" @change="choose($event,'font')"/><p>{{progress}}</p><a-list :data-source="uploads"><template #renderItem="{item}"><a-list-item>{{item.name}} · {{item.state}} {{item.error}}<a-button v-if="item.state==='failed'" @click="run(async()=>{await http.post(base+`uploads/${item.id}/complete/`);await refreshJobs()})">重试</a-button></a-list-item></template></a-list>
<a-list :data-source="assets.filter(a=>a.kind==='font')"><template #renderItem="{item}"><a-list-item>{{item.metadata.faces?.[0]?.family}} · {{(item.byte_size/1048576).toFixed(1)}} MB <a-button @click="addFace(item)">加入字面</a-button></a-list-item></template></a-list>
<a-radio-group v-model:value="draft.default_face"><div v-for="(f,i) in draft.faces" :key="f.id"><a-radio :value="f.id">{{f.label}} · {{f.postscript_name}}</a-radio><a-button type="link" @click="draft.faces.splice(i,1)">移出草稿</a-button></div></a-radio-group></a-tab-pane>
<a-tab-pane key="preview" tab="小样与展示"><a-input v-model:value="draft.recipe.text" placeholder="小样文案"/><a-space><label>背景<input type="color" v-model="draft.recipe.background"/></label><label>文字<input type="color" v-model="draft.recipe.color"/></label><a-button :loading="busy" @click="generate">用本地字体生成小样</a-button></a-space><p>生成图需核对缺字及真实字体效果后上传；也可使用独立工具生成并上传。</p><img v-if="specimenURL" :src="specimenURL" class="specimen"/>
<p>上传封面 <input type="file" accept="image/png,image/webp" @change="choose($event,'cover')"/></p><a-select v-model:value="draft.cover" :options="assetOptions('cover')" placeholder="选择已验证封面" style="width:100%"/><p>上传详情图 <input type="file" accept="image/png,image/webp" @change="choose($event,'preview')"/></p><a-select v-model:value="draft.previews" mode="multiple" :options="assetOptions('preview')" placeholder="选择已验证详情图" style="width:100%"/></a-tab-pane>
<a-tab-pane key="license" tab="授权资料"><a-form layout="vertical"><a-form-item label="授权来源"><a-input v-model:value="draft.license_source"/></a-form-item><a-form-item label="授权附件"><input type="file" accept=".txt,.pdf" @change="choose($event,'license')"/><a-select v-model:value="draft.license_asset" :options="assetOptions('license')"/></a-form-item><a-form-item label="确认许可范围"><a-checkbox-group v-model:value="draft.license_scopes" :options="[{value:'app',label:'App嵌入'},{value:'distribution',label:'字体分发'},{value:'paid_service',label:'付费服务'},{value:'print',label:'印制'}]"/></a-form-item><a-textarea v-model:value="draft.license_note" placeholder="核对依据"/><a-checkbox v-model:checked="draft.license_approved">已核对上述授权范围</a-checkbox></a-form></a-tab-pane>
<a-tab-pane key="pricing" tab="收费规则"><p>复用收费与权限中心：免费、Pro 专属、钻石购买、Pro 或钻石。保存字体草稿不会发布价格。</p><a-button @click="price">登记字体商品并管理收费策略</a-button><p>字体 ID：{{selected.id}}</p></a-tab-pane>
<a-tab-pane key="history" tab="发布记录"><a-button @click="versions">刷新历史版本</a-button><a-list :data-source="history"><template #renderItem="{item}"><a-list-item>v{{item.number}} · {{item.created_at}}<a-button @click="run(async()=>{await http.post(base+`families/${selected.id}/restore/`,{version:item.number,expected_revision:revision});await edit(selected.id)})">复制为草稿</a-button></a-list-item></template></a-list></a-tab-pane>
</a-tabs><footer><span>{{dirty?'有未保存修改':'草稿已保存'}}</span><a-button v-if="options.permissions.edit" :loading="busy" @click="run(save)">保存草稿</a-button><a-button @click="preview=true">手机预览</a-button><a-button v-if="options.permissions.publish" type="primary" :loading="busy" @click="publish">校验并发布</a-button></footer><a-alert v-if="checks.length" type="error" :message="checks.join('；')"/>
</template>
<a-modal v-model:open="newOpen" title="新建字体" :confirm-loading="busy" @ok="create"><a-input v-model:value="newTitle" placeholder="字体名称"/></a-modal>
<a-modal v-model:open="preview" title="客户端小样预览" :footer="null"><div v-if="draft" class="phone"><img :src="imageURL(draft.cover)" class="specimen"/><h3>{{draft.title}}</h3><p>{{draft.description}}</p><img v-for="id in draft.previews" :key="id" :src="imageURL(id)" class="specimen"/></div></a-modal>
</div></template>
<style scoped>.fonts-admin{padding:24px;background:white;min-height:80vh}header,footer{display:flex;align-items:center;gap:16px;padding:16px 0}header h2{flex:1}.thumb{width:56px;height:56px;border-radius:12px;vertical-align:middle;margin-right:12px}.specimen{width:240px;max-width:100%;border-radius:24px;margin:12px}.phone{text-align:center}footer{position:sticky;bottom:0;background:white;border-top:1px solid #eee;z-index:2}.ant-form{max-width:720px}.ant-table-wrapper{margin-top:20px}</style>
